/** Story dictation content (generated by scripts/dictation/build_story.py, see docs/dictation/04-content-pipeline.md). */

export interface StoryIndexEntry {
  id: string;                    // 'story-01'
  title: string;
  lessons: [number, number];
  block: number;
  sequences: number;
  sentences: number;
  contentVersion: string;
  file: string;                  // 'story-01.json'
}

export interface StoryIndex {
  version: 1;
  stories: StoryIndexEntry[];
}

export type SentenceFlag = 'digits' | 'ordinalDot' | 'ellipsis' | 'quoted' | 'long' | 'endsDigitDot';

export interface SentenceLink {
  s: number;                     // start offset in `text` (UTF-16 code units)
  e: number;                     // end offset, exclusive
  cards: string[];               // candidate card ids, preferred first
  lemma: string;
  kind: 'form' | 'separable' | 'phrase';
}

export interface SentenceSegment {
  text: string;
  speaker: string;
  speech?: string;
}

export interface Sentence {
  id: string;                    // stable, never reused ('s01q1n0007')
  hash: string;                  // sha256(text) first 12 hex
  text: string;                  // display and answer text (NFC, bold stripped)
  speaker: string;               // cast id, 'NARRATOR' for narration
  segments?: SentenceSegment[];  // only when narration and a quote are mixed
  speech?: string;               // text for TTS when it differs from `text`
  endMark: '.' | '!' | '?' | '…' | '';
  quoteBalance: number;          // opening minus closing double quotes in `text`
  flags: SentenceFlag[];
  links: SentenceLink[];
  grammar: string[];
}

export interface SequenceImage {
  key: string;                   // 'images/S01-Q1'
  w: number;
  h: number;
  alt: { fa: string; en: string };
}

export interface Sequence {
  id: string;                    // 'S01-Q1'
  order: number;
  title: string;
  situation: { fa: string; en: string };
  image: SequenceImage | null;
  sentences: Sentence[];
}

export interface Story {
  id: string;
  title: string;
  block: number;
  lessons: [number, number];
  contentVersion: string;
  speakersReviewed: boolean;
  grammarReviewed?: boolean;
  names: string[];               // proper names and protected words (never offered as new cards)
  sequences: Sequence[];
}

/** A grammar card (own-words German text, content/dictation/grammar/block-NN.json). */
export interface GrammarCard {
  id: string;                    // 'g-01-02-artikel-bestimmt-und-unbestimmt', fixed once published
  block: number;
  lesson: number;
  level: 'A1' | 'A2' | 'B1';
  title: string;                 // German title as in the book
  rule: string;                  // short explanation in German; "\n" separates paragraphs
  table?: { head: string[]; rows: string[][] };
  examples: { id: string; text: string }[];   // sentences from the stories, resolved at build time
  related?: string[];
}

/** story-NN.grammar.json: the cards used by one story and the first sentence that carries each point. */
export interface GrammarFile {
  storyId: string;
  block: number;
  cards: GrammarCard[];
  first: Record<string, string>;
}
